<?php require_once '../includes/db.php';require_once '../includes/functions.php';if(!empty($_SESSION['admin_id'])){header('Location: index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$email=trim($_POST['email']??'');$s=$conn->prepare("SELECT * FROM admins WHERE email=?");$s->bind_param('s',$email);$s->execute();$a=$s->get_result()->fetch_assoc();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];header('Location: index.php');exit;}$error='Invalid email or password.';}$title='Admin login';$adminPage=true;include '../includes/header.php';?><section class="login"><form class="form" method="post"><small>STORE MANAGEMENT</small><h1>Welcome back</h1><p>Sign in to manage your store.</p><?php if($error):?><div class="flash"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn dark full">Sign in</button><p class="muted">Create the first admin account using setup_admin.php in the project root.</p></form></section><?php include '../includes/footer.php';?>